module.exports = async (args) => {
  args.variables.user = args.variables.user || {};
  const cq = args.variables.user.cq || '30';
  const map = { '29': '29', '30': '30', '34': '34', '38': '37' };
  args.variables.user.qvbr = map[cq] || '30';
  args.jobLog('[map-qvbr] bucket cq' + cq + ' -> nvencc qvbr' + args.variables.user.qvbr);
  return { outputFileObj: args.inputFileObj, outputNumber: 1, variables: args.variables };
};
